script:
(function() {
    setTimeout(() => {
        if (typeof frappe === 'undefined' || !root_element) return;

        if (frappe.session.user === "Administrator") {
            const container = root_element.querySelector('#hr-card-horizontal');
            if (container) {
                container.innerHTML = `<div style="padding:10px;color:#888;">Admin View: Check-in disabled.</div>`;
            }
            return;
        }

        let timerInterval;
        // clock-independent timer: anchor on the server's computed worked-seconds and
        // count up using the LOCAL elapsed time since that fetch. Never subtract a
        // server timestamp from the device clock (that goes negative if the phone/PC
        // clock/timezone is behind real time).
        let anchorSec = 0, anchorAt = 0, running = false;
        let currentEmpId = null;
        let isProcessing = false;
        let lastClickTime = 0;

        const getEl = (sel) => root_element.querySelector(sel);
        const setSafeText = (id, val) => {
            const el = getEl('#' + id);
            if (el) el.innerText = val;
        };

        // If the device date/time is set wrong (e.g. a laptop left on a foreign
        // timezone/clock), warn the user. Uses the server's HTTP Date header (real
        // UTC from the NTP-synced server), so it's timezone-proof.
        function checkClockSkew() {
            try {
                fetch(window.location.origin + "/api/method/frappe.ping", { method: "GET", cache: "no-store" })
                    .then((resp) => {
                        const d = resp.headers.get("Date");
                        if (!d) return;
                        const skewMin = Math.round((Date.now() - new Date(d).getTime()) / 60000);
                        if (Math.abs(skewMin) > 5) {
                            frappe.msgprint({
                                title: "Please fix your device clock",
                                message: "Your device's date & time look off by about " + Math.abs(skewMin) +
                                    " minutes versus the server. Please set your date, time and time zone to " +
                                    "<b>automatic</b>, then refresh this page — otherwise your work timer may display incorrectly.",
                                indicator: "orange"
                            });
                        }
                    }).catch(() => {});
            } catch (e) {}
        }
        checkClockSkew();

        const parseDateTime = (str) => {
            if (!str) return null;
            return new Date(str.replace(' ', 'T'));
        };

        function updateTimerDisplay(ms) {
            ms = Math.max(0, ms); // never show negative time
            const s = Math.floor(ms / 1000);
            setSafeText('hr-box', String(Math.floor(s / 3600)).padStart(2, '0'));
            setSafeText('min-box', String(Math.floor((s % 3600) / 60)).padStart(2, '0'));
            setSafeText('sec-box', String(s % 60).padStart(2, '0'));
        }

        function runTimer() {
            if (!running) return;
            const secs = anchorSec + Math.max(0, (Date.now() - anchorAt) / 1000);
            updateTimerDisplay(secs * 1000);
        }

        function startTimer() {
            if (!timerInterval) timerInterval = setInterval(runTimer, 1000);
            runTimer();
        }
        function stopTimer() {
            if (timerInterval) { clearInterval(timerInterval); timerInterval = null; }
        }

        // ========================
        // FETCH EMPLOYEE
        // ========================
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Employee",
                filters: { user_id: frappe.session.user }
            },
            callback: (r) => {
                if (r.message) {
                    const emp = r.message;
                    currentEmpId = emp.name;
                    setSafeText('user-name', emp.employee_name);
                    setSafeText('user-desig', emp.designation || "Team Member");

                    const imgEl = getEl('#user-img');
                    if (imgEl) {
                        if (emp.image) {
                            imgEl.src = emp.image;
                        } else {
                            // fall back to the user's profile photo if the Employee record has none
                            frappe.call({
                                method: "frappe.client.get_value",
                                args: { doctype: "User", filters: { name: frappe.session.user }, fieldname: "user_image" },
                                callback: (ur) => {
                                    if (ur.message && ur.message.user_image) imgEl.src = ur.message.user_image;
                                }
                            });
                        }
                    }

                    fetchTodayStatus(emp.name);
                    loadWorkingHours();
                } else {
                    setSafeText('user-name', "Not Linked");
                    setSafeText('user-desig', "No Employee record");
                    setSafeText('checkin-status', "—");
                }
            }
        });

        // ========================
        // FETCH CHECKIN STATUS  (button label + status text only)
        // ========================
        function fetchTodayStatus(emp_id) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Employee Checkin",
                    filters: {
                        employee: emp_id,
                        time: ['>=', frappe.datetime.get_today()]
                    },
                    fields: ['log_type', 'time', 'device_id'],
                    order_by: 'time asc',
                    limit: 100
                },
                callback: (res) => {
                    const btn = getEl('#main-checkin-btn');
                    const statusEl = getEl('#checkin-status');
                    const logs = res.message || [];

                    const lastLog = logs[logs.length - 1];
                    const isIn = lastLog && lastLog.log_type === 'IN';

                    if (isIn) {
                        const tag = lastLog.device_id || "Active";
                        statusEl.innerText = "Shift Active • " + tag;
                        statusEl.style.color = "#2ecc71";
                        btn.innerText = "Check Out";
                        btn.style.background = "#e74c3c";
                        btn.disabled = false;
                    } else {
                        const hadActivity = logs.length > 0;
                        statusEl.innerText = hadActivity ? "Shift Ended" : "Yet to Check-in";
                        statusEl.style.color = hadActivity ? "#f39c12" : "#e74c3c";
                        btn.innerText = "Check In";
                        btn.style.background = "#171717";
                        btn.disabled = false;
                    }

                    isProcessing = false;
                    // the running timer is driven by loadWorkingHours (server worked-seconds)
                    loadWorkingHours();
                },
                error: () => {
                    // if the status refresh fails, still release the button
                    isProcessing = false;
                    const b = getEl('#main-checkin-btn');
                    if (b) { b.disabled = false; }
                }
            });
        }

        // ========================
        // WORKING HOURS  (authoritative worked-seconds from the server)
        // ========================
        function loadWorkingHours() {
            frappe.call({
                method: "get_today_working_hours",
                callback: function(r) {
                    if (!r.message) return;
                    const data = r.message;

                    const el = getEl('#work-hours-display');
                    if (el) {
                        el.innerText = "Today: " + data.worked + " / " + data.required;
                        el.style.color = data.color;
                        el.style.fontSize = "13px";
                        el.style.fontWeight = "600";
                    }

                    // anchor the live timer (clock-independent)
                    anchorSec = data.worked_seconds || 0;
                    anchorAt = Date.now();
                    running = !!data.is_checked_in;
                    if (running) {
                        startTimer();
                    } else {
                        stopTimer();
                        updateTimerDisplay(anchorSec * 1000);
                    }
                }
            });
        }

        setInterval(loadWorkingHours, 60000);




        // ========================
        // CHECKIN BUTTON
        // ========================
        function handleCheckin() {
            const now = Date.now();
            if (now - lastClickTime < 2000) return;
            if (isProcessing) return;

            lastClickTime = now;
            isProcessing = true;

            const self = getEl('#main-checkin-btn');
            if (self && self.disabled) { isProcessing = false; return; }

            if (!navigator.geolocation) {
                frappe.msgprint({
                    title: "Location Required",
                    message: "Your browser does not support geolocation. Please use Chrome or Firefox.",
                    indicator: "red"
                });
                isProcessing = false;
                return;
            }

            self.disabled = true;
            self.innerText = "Getting Location...";

            navigator.geolocation.getCurrentPosition(
                (pos) => {
                    // --- Reject imprecise location fixes (IP/WiFi fallback) that cause false "Work From Home".
                    const MAX_ACCURACY_M = 200;
                    const acc = pos.coords.accuracy;
                    if (acc == null || acc > MAX_ACCURACY_M) {
                        frappe.msgprint({
                            title: "Location Not Precise Enough",
                            message: "We couldn't confirm your location precisely (accuracy ~" + Math.round(acc || 0) + " m). Please turn on precise GPS / Location and try again, or check in from your mobile phone.",
                            indicator: "orange"
                        });
                        self.disabled = false;
                        self.innerText = "Check In / Out";
                        isProcessing = false;
                        return;
                    }

                    self.innerText = "Processing...";

                    frappe.call({
                        method: "custom_toggle_checkin",
                        args: {
                            latitude: pos.coords.latitude,
                            longitude: pos.coords.longitude,
                            accuracy: acc
                        },
                        callback: (r) => {
                            isProcessing = false;
                            self.disabled = false;
                            if (r.message && r.message.status === "success") {
                                const m = r.message;
                                frappe.show_alert({
                                    message: (m.log_type === 'IN' ? 'Checked In' : 'Checked Out') + " — " + m.location_type,
                                    indicator: m.log_type === 'IN' ? 'green' : 'orange'
                                }, 5);
                                fetchTodayStatus(currentEmpId);
                            } else {
                                self.innerText = "Check In / Out";
                                frappe.msgprint(
                                    r.message && r.message.error
                                        ? r.message.error
                                        : "Check-in failed. Please try again."
                                );
                            }
                        },
                        error: () => {
                            isProcessing = false;
                            self.disabled = false;
                            self.innerText = "Check In / Out";
                            frappe.show_alert({ message: "Something went wrong. Please try again.", indicator: "red" }, 5);
                        }
                    });
                },
                (err) => {
                    const messages = {
                        1: "Location permission was denied. Please enable location access in your browser settings.",
                        2: "Location could not be determined. Please check your GPS or network.",
                        3: "Location request timed out. Please try again in an open area."
                    };
                    frappe.msgprint({
                        title: "Location Error",
                        message: messages[err.code] || "Location access failed.",
                        indicator: "red"
                    });
                    self.disabled = false;
                    self.innerText = "Check In / Out";
                    isProcessing = false;
                },
                {
                    enableHighAccuracy: true,
                    timeout: 15000,
                    maximumAge: 0
                }
            );
        }

        const btn = getEl('#main-checkin-btn');
        if (btn) {
            btn.onclick = handleCheckin;
        }

    }, 800);
})();

(function () {
  setTimeout(function () {
    if (typeof frappe === 'undefined' || !root_element) return;
    var root = root_element;
    var monthEl = root.querySelector('#att-month');
    var gridEl = root.querySelector('#att-grid');
    var wdEl = root.querySelector('#att-weekdays');
    var legendEl = root.querySelector('#att-legend');
    if (!gridEl) return;

    var COLORS = {
      present: { bg: '#e7f8ef', dot: '#27ae60', label: 'Present (Office)' },
      wfh:     { bg: '#e8f1fd', dot: '#2f80ed', label: 'Work From Home / Mixed' },
      half:    { bg: '#fff4e5', dot: '#f39c12', label: 'Half Day' },
      leave:   { bg: '#fdeaea', dot: '#e74c3c', label: 'Leave' },
      absent:  { bg: '#fdeaea', dot: '#c0392b', label: 'Absent' },
      off:     { bg: '#f4f6f8', dot: '#c3ccd4', label: 'Week-off' },
      holiday: { bg: '#fff8e1', dot: '#e0a800', label: 'Holiday' }
    };
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(function (d) {
      var c = document.createElement('div'); c.innerText = d; wdEl.appendChild(c);
    });
    var legendKeys = ['present','wfh','half','leave','absent','off'];
    legendKeys.forEach(function (k) {
      var it = document.createElement('div');
      it.style.cssText = 'display:flex;align-items:center;gap:6px;';
      it.innerHTML = '<span style="width:12px;height:12px;border-radius:3px;background:' + COLORS[k].dot + ';display:inline-block;"></span>' + COLORS[k].label;
      legendEl.appendChild(it);
    });

    var view = new Date(); view.setDate(1);
    var empId = null;
    var today = new Date(); today.setHours(0, 0, 0, 0);

    function fmt(d) {
      return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    function getList(dt, filters, fields) {
      return new Promise(function (res) {
        frappe.call({
          method: 'frappe.client.get_list',
          args: { doctype: dt, filters: filters, fields: fields, limit_page_length: 0 },
          callback: function (r) { res((r && r.message) || []); },
          error: function () { res([]); }
        });
      });
    }

    frappe.call({
      method: 'frappe.client.get_value',
      args: { doctype: 'Employee', filters: { user_id: frappe.session.user }, fieldname: 'name' },
      callback: function (r) {
        if (r.message && r.message.name) { empId = r.message.name; render(); }
        else { monthEl.innerText = 'No employee linked to your account'; }
      }
    });

    function render() {
      monthEl.innerText = view.toLocaleString('default', { month: 'long', year: 'numeric' });
      var start = new Date(view.getFullYear(), view.getMonth(), 1);
      var end = new Date(view.getFullYear(), view.getMonth() + 1, 0);
      var s = fmt(start), e = fmt(end);
      Promise.all([
        new Promise(function (res) {
          frappe.call({ method: 'get_my_holidays', args: { from_date: s, to_date: e },
                        callback: function (r) { res(r.message || []); },
                        error: function () { res([]); } });
        }),
        getList('Attendance', { employee: empId, attendance_date: ['between', [s, e]] }, ['attendance_date', 'status', 'working_hours']),
        getList('Employee Checkin', { employee: empId, time: ['between', [s + ' 00:00:00', e + ' 23:59:59']] }, ['time', 'device_id'])
      ]).then(function (out) {
        var holidays = out[0], att = out[1], checkins = out[2];
        var holidayBy = {};
        holidays.forEach(function (h) { if (!h.weekly_off) holidayBy[h.date] = h.description || 'Holiday'; });
        var map = {};
        att.forEach(function (a) {
          var m = (map[a.attendance_date] = map[a.attendance_date] || {});
          m.status = a.status;
          m.hours = a.working_hours;
        });
        checkins.forEach(function (c) {
          var d = String(c.time).slice(0, 10);
          var m = (map[d] = map[d] || {});
          if (c.device_id === 'Work From Home') m.wfh = true;
          else if (c.device_id === 'Office') m.office = true;
        });
        draw(start, end, map, holidayBy);
      });
    }

    function classify(dateObj, info, isHoliday) {
      var isWeekend = (dateObj.getDay() === 0 || dateObj.getDay() === 6);
      var st = info && info.status;
      if (st === 'On Leave') return 'leave';
      if (st === 'Absent') return 'absent';
      if (st === 'Half Day') return 'half';
      if (st === 'Present' || st === 'Work From Home') {
        if (info.wfh) return 'wfh';
        return 'present';
      }
      if (info && (info.office || info.wfh)) return info.wfh && !info.office ? 'wfh' : 'present';
      if (isHoliday) return 'holiday';
      if (isWeekend) return 'off';
      if (dateObj < today) return 'absent';
      return null; // future working day, no data
    }

    function draw(start, end, map, holidayBy) {
      holidayBy = holidayBy || {};
      gridEl.innerHTML = '';
      var lead = start.getDay();
      for (var i = 0; i < lead; i++) gridEl.appendChild(document.createElement('div'));
      var days = end.getDate();
      for (var day = 1; day <= days; day++) {
        var dObj = new Date(view.getFullYear(), view.getMonth(), day);
        var key = fmt(dObj);
        var info = map[key];
        var holidayName = holidayBy[key];
        var kind = classify(dObj, info, !!holidayName);
        var cell = document.createElement('div');
        var isToday = (dObj.getTime() === today.getTime());
        var bg = kind ? COLORS[kind].bg : '#fff';
        var border = isToday ? '2px solid #171717' : '1px solid #edf1f5';
        cell.style.cssText = 'position:relative;min-height:52px;border:' + border + ';border-radius:10px;background:' + bg + ';padding:6px 8px;box-sizing:border-box;';
        var num = document.createElement('div');
        num.innerText = day;
        num.style.cssText = 'font-size:12px;font-weight:600;color:#5a6b78;';
        cell.appendChild(num);
        if (kind) {
          var dot = document.createElement('span');
          dot.style.cssText = 'position:absolute;bottom:8px;left:8px;width:9px;height:9px;border-radius:50%;background:' + COLORS[kind].dot + ';';
          cell.appendChild(dot);
          cell.title = holidayName ? holidayName : COLORS[kind].label;
        }
        // worked hours on days that were actually worked
        var hrs = info && info.hours;
        if (hrs && ['present', 'wfh', 'half'].indexOf(kind) !== -1) {
          var h = Math.floor(hrs), m = Math.round((hrs - h) * 60);
          if (m === 60) { h += 1; m = 0; }
          var hEl = document.createElement('div');
          hEl.innerText = h + ':' + (m < 10 ? '0' + m : m);
          hEl.style.cssText = 'position:absolute;bottom:5px;right:7px;font-size:10.5px;font-weight:700;color:#33475b;';
          cell.appendChild(hEl);
          cell.title = COLORS[kind].label + ' \u2022 ' + h + 'h ' + m + 'm worked';
        }
        gridEl.appendChild(cell);
      }
    }

    root.querySelector('#att-prev').onclick = function () { view.setMonth(view.getMonth() - 1); render(); };
    root.querySelector('#att-next').onclick = function () { view.setMonth(view.getMonth() + 1); render(); };
  }, 400);
})();

(function () {
    // The `roles` table on a Custom HTML Block does NOT gate delivery -
    // get_custom_blocks_for_user filters only on private/owner - so every
    // employee was served the HR dashboard on Home. Hide it here instead.
    if (typeof frappe !== 'undefined' && !(frappe.user.has_role('HR Manager')
            || frappe.user.has_role('System Manager'))) {
        if (typeof root_element !== 'undefined' && root_element) {
            root_element.innerHTML = '';
            var host = root_element.host || (root_element.getRootNode && root_element.getRootNode().host);
            if (host && host.closest) {
                var blk = host.closest('.widget, .custom-block, .ce-block');
                if (blk) { blk.style.display = 'none'; }
            }
        }
        return;
    }

  setTimeout(function () {
    if (typeof frappe === 'undefined' || !root_element) return;
    var root = root_element;
    var $ = function (s) { return root.querySelector(s); };
    var empSel = $('#dash-emp'), fromEl = $('#dash-from'), toEl = $('#dash-to');
    var tilesEl = $('#dash-tiles'), headEl = $('#dash-head'), bodyEl = $('#dash-body');
    if (!bodyEl) return;

    var LATE_AFTER = 10 * 60 + 45;    // 10:45
    var EARLY_BEFORE = 18 * 60 + 45;  // 18:45
    var employees = [];

    function fmt(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
    function today() { return new Date(); }
    function getList(dt, filters, fields) {
      return new Promise(function (res) {
        frappe.call({ method: 'frappe.client.get_list', args: { doctype: dt, filters: filters, fields: fields, limit_page_length: 0 }, callback: function (r) { res((r && r.message) || []); }, error: function () { res([]); } });
      });
    }
    function mins(t) { var p = String(t).slice(11, 16).split(':'); return (+p[0]) * 60 + (+p[1]); }
    function hhmm(t) { return String(t).slice(11, 16); }
    function fmtDur(sec) { var h = Math.floor(sec / 3600); var m = Math.floor((sec % 3600) / 60); return h + 'h ' + String(m).padStart(2, '0') + 'm'; }
    function daysBetween(a, b) { var out = [], d = new Date(a); while (d <= b) { out.push(new Date(d)); d.setDate(d.getDate() + 1); } return out; }
    function badge(t, c) { return '<span style="background:' + c + '18;color:' + c + ';padding:2px 8px;border-radius:20px;font-size:11px;font-weight:600;">' + t + '</span>'; }
    function tile(l, v, c) { return '<div style="background:' + c + '11;border:1px solid ' + c + '33;border-radius:10px;padding:11px 13px;"><div style="font-size:21px;font-weight:700;color:' + c + ';">' + v + '</div><div style="font-size:10.5px;color:#5a6b78;text-transform:uppercase;letter-spacing:.4px;">' + l + '</div></div>'; }

    // per employee-day metrics from that day's checkin logs
    function dayMetrics(logs) {
      logs = logs.slice().sort(function (a, b) { return a.time < b.time ? -1 : 1; });
      var ins = logs.filter(function (l) { return l.log_type === 'IN'; });
      var outs = logs.filter(function (l) { return l.log_type === 'OUT'; });
      var firstIn = ins.length ? ins[0].time : null, lastOut = outs.length ? outs[outs.length - 1].time : null;
      var sec = 0, lastInT = null;
      logs.forEach(function (l) { if (l.log_type === 'IN') lastInT = new Date(l.time.replace(' ', 'T')); else if (l.log_type === 'OUT' && lastInT) { sec += (new Date(l.time.replace(' ', 'T')) - lastInT) / 1000; lastInT = null; } });
      var wfh = logs.some(function (l) { return String(l.device_id || '').toLowerCase().indexOf('home') !== -1; });
      return { wfh: wfh, in: firstIn, out: lastOut, worked: sec, late: firstIn ? mins(firstIn) > LATE_AFTER : false, early: lastOut ? mins(lastOut) < EARLY_BEFORE : false, has: logs.length > 0 };
    }

    function load() {
      var from = fromEl.value, to = toEl.value; if (!from || !to) return;
      if (from > to) { var t = from; from = to; to = from; }
      var empFilter = empSel.value; // "" = all
      bodyEl.innerHTML = '<tr><td colspan="8" style="padding:14px;color:#8d99a6;">Loading…</td></tr>';
      var empFilters = { status: 'Active' }; if (empFilter) empFilters.name = empFilter;
      Promise.all([
        getList('Employee', empFilters, ['name', 'employee_name', 'department']),
        getList('Employee Checkin', { time: ['between', [from + ' 00:00:00', to + ' 23:59:59']] }, ['employee', 'log_type', 'time', 'device_id']),
        getList('Leave Application', { status: 'Approved', docstatus: 1, from_date: ['<=', to], to_date: ['>=', from] }, ['employee', 'from_date', 'to_date']),
        getList('Work From Home Request', { workflow_state: 'Approved', from_date: ['<=', to], to_date: ['>=', from] }, ['employee', 'from_date', 'to_date'])
      ]).then(function (out) {
        var emps = out[0], checkins = out[1], leaves = out[2], wfhReqs = out[3] || [];
        // a day covered by an APPROVED WFH request counts as work-from-home even
        // if the check-in GPS didn't classify it that way
        function wfhApproved(emp, dateStr) {
          return wfhReqs.some(function (w) { return w.employee === emp && String(w.from_date) <= dateStr && String(w.to_date) >= dateStr; });
        }
        var byEmpDay = {};
        checkins.forEach(function (c) { var d = String(c.time).slice(0, 10); var k = c.employee + '|' + d; (byEmpDay[k] = byEmpDay[k] || []).push(c); });
        function onLeave(emp, dateStr) { return leaves.some(function (l) { return l.employee === emp && String(l.from_date) <= dateStr && String(l.to_date) >= dateStr; }); }
        var days = daysBetween(new Date(from), new Date(to));
        var tnow = new Date(); tnow.setHours(0, 0, 0, 0);
        var sum = { present: 0, late: 0, early: 0, absent: 0, leave: 0, wfh: 0 };
        var singleEmp = !!empFilter;

        if (singleEmp) {
          // day-by-day for one employee
          headEl.innerHTML = ['Date', 'Check-in', 'Check-out', 'Worked', 'Late', 'Early Exit', 'Status'].map(function (c) { return '<th style="text-align:left;padding:8px 10px;border-bottom:2px solid #edf1f5;color:#8d99a6;font-weight:600;white-space:nowrap;">' + c + '</th>'; }).join('');
          var rows = days.map(function (dObj) {
            var ds = fmt(dObj), weekend = dObj.getDay() === 0 || dObj.getDay() === 6;
            var m = dayMetrics(byEmpDay[empFilter + '|' + ds] || []);
            if (wfhApproved(empFilter, ds)) m.wfh = true;
            var st, col;
            if (onLeave(empFilter, ds)) { st = 'On Leave'; col = '#2f80ed'; sum.leave++; }
            else if (m.has) { st = m.wfh ? 'Present (WFH)' : 'Present'; col = '#27ae60'; sum.present++; if (m.wfh) sum.wfh++; if (m.late) sum.late++; if (m.early) sum.early++; }
            else if (weekend) { st = 'Week-off'; col = '#8d99a6'; }
            else if (dObj <= tnow) { st = 'Absent'; col = '#c0392b'; sum.absent++; }
            else { st = '—'; col = '#c3ccd4'; }
            return '<tr style="border-bottom:1px solid #f2f5f8;"><td style="padding:8px 10px;font-weight:600;color:#1f272e;white-space:nowrap;">' + ds + ' <span style="color:#9aa7b2;font-weight:400;">' + dObj.toLocaleDateString('default', { weekday: 'short' }) + '</span></td>' +
              '<td style="padding:8px 10px;">' + (m.in ? hhmm(m.in) : '—') + '</td><td style="padding:8px 10px;">' + (m.out ? hhmm(m.out) : '—') + '</td>' +
              '<td style="padding:8px 10px;font-weight:600;">' + (m.worked > 0 ? fmtDur(m.worked) : '—') + '</td>' +
              '<td style="padding:8px 10px;">' + (m.late ? badge('LATE', '#e67e22') : '') + '</td><td style="padding:8px 10px;">' + (m.early ? badge('EARLY', '#8e44ad') : '') + '</td>' +
              '<td style="padding:8px 10px;">' + badge(st, col) + '</td></tr>';
          });
          bodyEl.innerHTML = rows.join('');
        } else {
          // aggregate per employee over the range
          headEl.innerHTML = ['Employee', 'Department', 'Present', 'WFH', 'Late', 'Early Exit', 'Absent', 'On Leave'].map(function (c) { return '<th style="text-align:left;padding:8px 10px;border-bottom:2px solid #edf1f5;color:#8d99a6;font-weight:600;white-space:nowrap;">' + c + '</th>'; }).join('');
          var rows2 = emps.map(function (e) {
            var r = { present: 0, late: 0, early: 0, absent: 0, leave: 0, wfh: 0 };
            days.forEach(function (dObj) {
              var ds = fmt(dObj), weekend = dObj.getDay() === 0 || dObj.getDay() === 6;
              if (onLeave(e.name, ds)) { r.leave++; return; }
              var m = dayMetrics(byEmpDay[e.name + '|' + ds] || []);
              if (m.has) { r.present++; if (m.wfh || wfhApproved(e.name, ds)) r.wfh++; if (m.late) r.late++; if (m.early) r.early++; }
              else if (!weekend && dObj <= tnow) r.absent++;
            });
            sum.present += r.present; sum.late += r.late; sum.early += r.early; sum.absent += r.absent; sum.leave += r.leave; sum.wfh += r.wfh;
            return { name: e.employee_name, dept: (e.department || '').replace(' - LA', ''), r: r };
          });
          rows2.sort(function (a, b) { return b.r.late - a.r.late || (a.name < b.name ? -1 : 1); });
          bodyEl.innerHTML = rows2.map(function (x) {
            return '<tr style="border-bottom:1px solid #f2f5f8;"><td style="padding:8px 10px;font-weight:600;color:#1f272e;">' + x.name + '</td><td style="padding:8px 10px;color:#5a6b78;">' + (x.dept || '—') + '</td>' +
              '<td style="padding:8px 10px;">' + x.r.present + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.wfh ? badge(x.r.wfh, '#1263d1') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.late ? badge(x.r.late, '#e67e22') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.early ? badge(x.r.early, '#8e44ad') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.absent ? badge(x.r.absent, '#c0392b') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.leave || '0') + '</td></tr>';
          }).join('') || '<tr><td colspan="8" style="padding:14px;color:#8d99a6;">No employees</td></tr>';
        }
        tilesEl.innerHTML = tile('Present', sum.present, '#27ae60') + tile('WFH', sum.wfh, '#1263d1') + tile('Late In', sum.late, '#e67e22') + tile('Early Out', sum.early, '#8e44ad') + tile('Absent', sum.absent, '#c0392b') + tile('On Leave', sum.leave, '#2f80ed');
      });
    }

    function setRange(a, b) { fromEl.value = fmt(a); toEl.value = fmt(b); load(); }
    $('#dash-today').onclick = function () { var d = today(); setRange(d, d); };
    $('#dash-week').onclick = function () { var d = today(), day = (d.getDay() + 6) % 7, mon = new Date(d); mon.setDate(d.getDate() - day); setRange(mon, d); };
    $('#dash-month').onclick = function () { var d = today(); setRange(new Date(d.getFullYear(), d.getMonth(), 1), d); };
    empSel.onchange = load; fromEl.onchange = load; toEl.onchange = load;

    // populate employee dropdown, then default to today
    getList('Employee', { status: 'Active' }, ['name', 'employee_name']).then(function (list) {
      employees = list;
      var opts = '<option value="">All employees</option>';
      list.sort(function (a, b) { return a.employee_name < b.employee_name ? -1 : 1; }).forEach(function (e) { opts += '<option value="' + e.name + '">' + e.employee_name + '</option>'; });
      empSel.innerHTML = opts;
      var d = today(); fromEl.value = fmt(d); toEl.value = fmt(d); load();
    });
  }, 400);
})();

(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lv-leave-body');
