            body.innerHTML = '<div style="color:#8a94a0;font-size:12.5px;">' +
                             'Admin view - leave balance is shown to employees.</div>';
            return;
        }

        function stat(label, value, bg, fg) {
            return '<div style="background:' + bg + ';border-radius:10px;padding:12px 14px;">' +
                   '<div style="font-size:12px;font-weight:600;color:' + fg + ';">' + label + '</div>' +
                   '<div style="font-size:22px;font-weight:700;color:#1f272e;margin-top:2px;">' + value + '</div>' +
                   '</div>';
        }

        frappe.call({
            method: 'get_my_leave_balance',
            callback: function (r) {
                var d = r.message || {};
                var rows = d.rows || [];
                if (!rows.length) {
                    body.innerHTML = '<div style="color:#8a94a0;font-size:12.5px;">' +
                                     'No leave allocated yet. Please check with HR.</div>';
                    return;
                }
                var html = stat('Total Allocated', d.allocated || 0, '#f1f4f8', '#5a6b78') +
                           stat('Taken', d.taken || 0, '#fff1e0', '#e8730c') +
                           stat('Balance', d.balance || 0, '#e7f7ee', '#17794f');
                if (rows.length > 1) {
                    html += rows.map(function (x) {
                        return '<div style="background:#e8f1ff;border-radius:10px;padding:12px 14px;">' +
                               '<div style="font-size:12px;font-weight:600;color:#1263d1;">' +
                                 frappe.utils.escape_html(x.leave_type) + '</div>' +
                               '<div style="font-size:22px;font-weight:700;color:#1f272e;margin-top:2px;">' +
                                 (x.balance || 0) + '<span style="font-size:12px;font-weight:600;color:#8a94a0;"> left</span></div>' +
                               '<div style="font-size:11px;color:#6b7885;margin-top:2px;">' +
                                 (x.allocated || 0) + ' allocated \u00b7 ' + (x.taken || 0) + ' taken</div>' +
                               '</div>';
                    }).join('');
                } else {
                    html += '<div style="background:#e8f1ff;border-radius:10px;padding:12px 14px;">' +
