(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lv-org-body');
        if (!body) return;

        frappe.call({
            method: 'get_org_chart',
            callback: function (r) {
                var rows = r.message || [];
                if (!rows.length) { body.innerHTML = '<div style="color:#8a94a0;">No employees.</div>'; return; }

                var byId = {}, kids = {};
                rows.forEach(function (e) { byId[e.name] = e; kids[e.name] = []; });
                var roots = [];
                rows.forEach(function (e) {
                    if (e.reports_to && kids[e.reports_to]) { kids[e.reports_to].push(e); }
                    else { roots.push(e); }
                });

                function person(e, depth) {
                    var children = kids[e.name] || [];
                    var initials = (e.employee_name || '?').split(' ').map(function (w) { return w[0]; })
                                     .join('').slice(0, 2).toUpperCase();
                    var meStyle = e.is_me ? 'background:#e7f7ee;border-color:#17794f55;' : 'background:#fff;';
                    var second = e.reports_to_2 && byId[e.reports_to_2]
                        ? ' <span style="color:#8a94a0;font-size:10.5px;">also reports to ' +
                          frappe.utils.escape_html(byId[e.reports_to_2].employee_name) + '</span>' : '';
                    var html = '<div style="margin:3px 0 3px ' + (depth * 18) + 'px;">' +
                        '<div style="display:inline-flex;align-items:center;gap:8px;border:1px solid #edf1f5;' +
                        'border-radius:8px;padding:5px 10px;' + meStyle + '">' +
                        '<span style="width:22px;height:22px;border-radius:50%;background:#1F4E78;color:#fff;' +
                        'display:inline-flex;align-items:center;justify-content:center;font-size:9.5px;' +
                        'font-weight:700;">' + initials + '</span>' +
                        '<span style="font-weight:600;color:#1f272e;">' +
                          frappe.utils.escape_html(e.employee_name) + (e.is_me ? ' (you)' : '') + '</span>' +
                        (e.designation ? '<span style="color:#6b7885;font-size:11.5px;">' +
                          frappe.utils.escape_html(e.designation) + '</span>' : '') +
                        (e.department ? '<span style="color:#9aa7b2;font-size:11px;">' +
                          frappe.utils.escape_html(e.department) + '</span>' : '') +
                        second + '</div></div>';
                    children.forEach(function (c) { html += person(c, depth + 1); });
                    return html;
                }

                body.innerHTML = '<div style="max-height:340px;overflow:auto;">' +
                                 roots.map(function (e) { return person(e, 0); }).join('') + '</div>';
            }
        });
    }, 700);
})();
